/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import jakarta.enterprise.context.ApplicationScoped;

/**
 * Creates the task of an issue in the issue tracker ({@code app.observe.tracker.*}):
 * <ul>
 * <li>{@code redmine}: {@code POST <url>/issues.json} with the api key; the task is
 * {@code <url>/issues/<id>}.</li>
 * <li>{@code webhook}: {@code POST <url>} with the issue as JSON; it answers {@code {"url":
 * ...}}.</li>
 * <li>{@code none} (default): not available.</li>
 * </ul>
 */
@ApplicationScoped
public class IssueTracker {

  private final String type;
  private final String url;
  private final String apiKey;
  private final String project;
  private final ObjectMapper mapper = new ObjectMapper();
  private final HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5))
      .followRedirects(HttpClient.Redirect.NEVER).build();

  public IssueTracker(
      final @ConfigProperty(name = "app.observe.tracker.type", defaultValue = "none") String type,
      final @ConfigProperty(name = "app.observe.tracker.url") Optional<String> url,
      final @ConfigProperty(name = "app.observe.tracker.api-key") Optional<String> apiKey,
      final @ConfigProperty(name = "app.observe.tracker.project") Optional<String> project) {
    this.type = type.trim().toLowerCase(java.util.Locale.ROOT);
    this.url = url.orElse("").replaceAll("/+$", "");
    this.apiKey = apiKey.orElse("");
    this.project = project.orElse("");
  }

  public boolean available() {
    return !"none".equals(type) && !url.isEmpty();
  }

  /** Creates the task and returns its URL. */
  public String create(final String title, final String description) {
    if (!available()) {
      throw new IllegalStateException("No issue tracker configured (app.observe.tracker.type)");
    }
    try {
      if ("redmine".equals(type)) {
        Map<String, Object> issue = new LinkedHashMap<>();
        issue.put("project_id", project);
        issue.put("subject", title.length() > 250 ? title.substring(0, 249) + "…" : title);
        issue.put("description", description);
        JsonNode answer = post(url + "/issues.json", Map.of("issue", issue), apiKey);
        return url + "/issues/" + answer.path("issue").path("id").asText();
      }
      JsonNode answer = post(url, Map.of("title", title, "description", description), null);
      return answer.path("url").asText(url);
    } catch (IOException ex) {
      throw new IllegalStateException("The issue tracker failed: " + ex.getMessage(), ex);
    } catch (InterruptedException ex) {
      Thread.currentThread().interrupt();
      throw new IllegalStateException("Interrupted", ex);
    }
  }

  private JsonNode post(final String target, final Object body, final String key)
      throws IOException, InterruptedException {
    HttpRequest.Builder request = HttpRequest.newBuilder(URI.create(target))
        .timeout(Duration.ofSeconds(15)).header("Content-Type", "application/json")
        .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body)));
    if (null != key && !key.isBlank()) {
      request.header("X-Redmine-API-Key", key);
    }
    HttpResponse<String> response =
        http.send(request.build(), HttpResponse.BodyHandlers.ofString());
    if (response.statusCode() / 100 != 2) {
      throw new IOException("status " + response.statusCode());
    }
    return null == response.body() || response.body().isBlank() ? mapper.createObjectNode()
        : mapper.readTree(response.body());
  }
}
